namespace UnityEngine {
 public struct Quaternion {public float x,y,z;public static Quaternion Euler(float x,float y,float z){return new Quaternion{x=x,y=y,z=z};}}
 public class Transform {public Quaternion localRotation;public GameObject gameObject;public Transform(){gameObject=new GameObject(this);}}
 public class GameObject {public Transform transform;public Light component;public GameObject(Transform t){transform=t;}public T GetComponent<T>() where T:class{return component as T;}public T AddComponent<T>() where T:class,new(){var value=new T();if(value is Light){component=value as Light;component.transform=transform;}return value;}}
 public enum LightType {Spot,Point}public enum LightRenderMode {Auto,ForcePixel}public enum LightShadows {None,Hard}
 public struct Color {public float r,g,b,a;public Color(float r,float g,float b,float a){this.r=r;this.g=g;this.b=b;this.a=a;}}
 public class Light {public string name="RW_DoorSpot";public bool enabled;public LightType type;public LightRenderMode renderMode;public float range,spotAngle,intensity;public Color color;public int cullingMask;public LightShadows shadows;public Transform transform=new Transform();}
 public class MaterialPropertyBlock {public Color color;public int untouched;public void SetColor(string key,Color c){color=c;}}
 public class Renderer {public string name="RW_DoorLightLens";public Color color;public int untouched=42;public void GetPropertyBlock(MaterialPropertyBlock b){b.color=color;b.untouched=untouched;}public void SetPropertyBlock(MaterialPropertyBlock b){color=b.color;untouched=b.untouched;}}
