public enum KSPActionGroup {None,Light}public class KSPActionParam {}public enum StartState {Editor,Flight}
public class BasePAWGroup {public string name;public BasePAWGroup(string n,string title,bool collapsed){name=n;}}
public class BaseEvent {public string name;public bool active=true,guiActive=true,guiActiveEditor=true;public BasePAWGroup group;}
public class BaseField {public BasePAWGroup group;}
public class BaseAction {public bool active=true;}
public class BaseEventList:List<BaseEvent> {public bool Contains(string n){return Find(e=>e.name==n)!=null;}public BaseEvent this[string n]{get{return Find(e=>e.name==n);}}}
public class PartModule {public Part part;public Vessel vessel{get{return part==null?null:part.vessel;}}public BaseEventList Events=new BaseEventList();public List<BaseField> Fields=new List<BaseField>();public List<BaseAction> Actions=new List<BaseAction>();public virtual void OnStart(StartState s){}public virtual void OnStartFinished(StartState s){}public virtual string GetInfo(){return "";}}
public class ModuleColorChanger:PartModule {public string moduleID;public bool animState;}
public class ModuleEngines:PartModule {public bool running=true;public int shutdowns;public void Shutdown(){running=false;shutdowns++;}}
public class ModuleDecouple:PartModule {public bool isDecoupled;public int calls;public ModuleEngines engine;public void Decouple(){if(engine!=null&&engine.running)throw new Exception("Release while engine still running");isDecoupled=true;calls++;}}
public class Vessel {public bool loaded=true,packed;}
public class Part {public Vessel vessel=new Vessel();public List<PartModule> modules=new List<PartModule>();public List<UnityEngine.Light> lights=new List<UnityEngine.Light>();public List<UnityEngine.Renderer> renderers=new List<UnityEngine.Renderer>();public UnityEngine.Transform mount;public double ec=1,consumed;public int requests;public List<T> FindModulesImplementing<T>(){var list=new List<T>();foreach(var m in modules)if(m is T)list.Add((T)(object)m);return list;}public T FindModuleImplementing<T>() where T:class {foreach(var m in modules)if(m is T)return m as T;return null;}public List<T> FindModelComponents<T>(string n){var list=new List<T>();foreach(var l in lights)if(l.name==n&&l is T)list.Add((T)(object)l);foreach(var r in renderers)if(r.name==n&&r is T)list.Add((T)(object)r);return list;}public UnityEngine.Transform FindModelTransform(string n){return mount;}public double RequestResource(string name,double amount){if(name!="ElectricCharge")throw new Exception("Wrong fuel");requests++;double taken=Math.Min(ec,amount);ec-=taken;consumed+=taken;return taken;}}
public static class HighLogic {public static bool LoadedSceneIsFlight=true,LoadedSceneIsEditor;}
public static class LightingReleaseTest {
 static int count;static void Check(bool value,string msg){count++;if(!value)throw new Exception(msg);}
 static ModuleRWExteriorLight Light(bool cabinOn=true){var p=new Part();p.lights.Add(new UnityEngine.Light());p.renderers.Add(new UnityEngine.Renderer());p.modules.Add(new ModuleColorChanger{moduleID="RW_HAB_250_CabinLights",animState=cabinOn});var m=new ModuleRWExteriorLight{part=p};m.Events.Add(new BaseEvent{name="LightsOn"});m.Fields.Add(new BaseField());m.OnStart(StartState.Flight);m.OnStartFinished(StartState.Flight);return m;}
 public static void Run(){
 foreach(bool editor in new[]{false,true})foreach(bool cabin in new[]{false,true}){
  HighLogic.LoadedSceneIsEditor=editor;HighLogic.LoadedSceneIsFlight=!editor;var m=Light(cabin);m.FixedUpdate();m.LateUpdate();var lamp=m.part.lights[0];Check(lamp.enabled==cabin,"Real emitter does not follow cabin");Check(lamp.type==UnityEngine.LightType.Spot&&lamp.renderMode==UnityEngine.LightRenderMode.ForcePixel,"Per-pixel terrain spot not forced");Check(lamp.cullingMask==-1&&lamp.range==10&&lamp.spotAngle==100&&lamp.intensity==4,"Light coverage/power wrong");Check(lamp.transform.localRotation.x==60,"Spot must face downward/outward");Check(lamp.shadows==UnityEngine.LightShadows.None,"Fixture may self-shadow");Check((m.part.renderers[0].color.r>0)==cabin,"Lens state not actual illumination state");Check(m.part.renderers[0].untouched==42,"Other renderer properties changed");Check(m.Events[0].group.name=="RWLighting","UI grouping lost");Check(editor?m.part.requests==0:Math.Abs(m.part.consumed-(cabin?.03*.02:0))<1e-8,"Incorrect EC consumption");
  m.LightsOff();m.FixedUpdate();Check(!lamp.enabled&&!m.followCabinLights,"Independent off failed");m.LightsOn();m.FixedUpdate();Check(lamp.enabled,"Independent on failed");m.LinkToCabin();m.FixedUpdate();Check(lamp.enabled==cabin&&m.followCabinLights,"Cabin relink failed");
 }
 HighLogic.LoadedSceneIsEditor=false;HighLogic.LoadedSceneIsFlight=true;var light=Light();light.part.ec=0;light.FixedUpdate();Check(!light.part.lights[0].enabled&&light.status.Contains("electric charge"),"No-EC light remains on");light.part.ec=1;light.FixedUpdate();Check(light.part.lights[0].enabled,"Light failed to recover when EC returns");int before=light.part.requests;light.part.vessel.packed=true;light.FixedUpdate();Check(!light.part.lights[0].enabled&&light.part.requests==before,"Packed vessel consumes/renders light");light.part.vessel.packed=false;light.FixedUpdate();Check(light.part.lights[0].enabled,"Unpack failed to restore light");
 var fallbackPart=new Part{mount=new UnityEngine.Transform()};var fallback=new ModuleRWExteriorLight{part=fallbackPart,isOn=true,followCabinLights=false};fallback.OnStart(StartState.Flight);fallback.FixedUpdate();Check(fallbackPart.mount.gameObject.component!=null&&fallbackPart.mount.gameObject.component.enabled,"Missing native Light component fallback failed");
 new ModuleRWExteriorLight().OnStart(StartState.Flight);new ModuleRWExteriorLight().FixedUpdate();Check(true,"Missing part safe");
 var p2=new Part();var engine=new ModuleEngines{part=p2};var dec=new ModuleDecouple{part=p2,engine=engine};dec.Events.Add(new BaseEvent{name="Decouple"});dec.Actions.Add(new BaseAction());p2.modules.Add(engine);p2.modules.Add(dec);var release=new ModuleRWPodRelease{part=p2};release.Events.Add(new BaseEvent{name="ReleasePod"});release.OnStart(StartState.Flight);release.OnStartFinished(StartState.Flight);Check(dec.calls==0&&engine.running,"Release occurs during startup");Check(!dec.Events[0].guiActive&&!dec.Events[0].guiActiveEditor&&!dec.Actions[0].active,"Unsafe duplicate stock release controls remain");HighLogic.LoadedSceneIsFlight=false;release.ReleasePod();Check(dec.calls==0,"Editor executes flight separation");HighLogic.LoadedSceneIsFlight=true;release.ReleasePod();Check(!engine.running&&engine.shutdowns==1&&dec.calls==1&&dec.isDecoupled,"Whole-pod stock release / engine shutdown failed");Check(!release.Events[0].active,"Released pod can release again");release.ReleasePod();Check(dec.calls==1&&engine.shutdowns==1,"Repeated release is not safe");release.OnStartFinished(StartState.Flight);Check(!release.Events[0].active,"Reload resurrects release");new ModuleRWPodRelease().ReleasePod();Check(true,"Missing release safe");
 Console.WriteLine("PASS "+count+" real-light/pod-release assertions: powered emitters, cabin link, manual override, EC, editor/flight, packing, fallback, engine shutdown and stock whole-part release");
 }
}
